template<typename T>
inline constexpr size_t tuple_size_v = tuple_size<std::remove_cvref_t<T>>::value;

template<size_t I, typename... Ts>
struct tuple_element<I, tuple<Ts...>> {
    static_assert(I < sizeof...(Ts), "tuple element index is out of range");
    using type = std::tuple_element_t<I, std::tuple<Ts...>>;
};

template<size_t I, typename T>
using tuple_element_t = typename tuple_element<I, std::remove_cvref_t<T>>::type;

