template<size_t I, typename... Ts>
constexpr decltype(auto) get(tuple<Ts...> &&value) noexcept {
    return std::move(get<I>(value));
}

template<size_t I, typename... Ts>
constexpr decltype(auto) get(const tuple<Ts...> &&value) noexcept {
    return std::move(get<I>(value));
}

template<typename T, typename... Ts>
requires(detail::tuple_type_count_v<T, Ts...> == 1u)
constexpr decltype(auto) get(tuple<Ts...> &value) noexcept {
    return get<detail::tuple_type_index<T, Ts...>::value>(value);
}

template<typename T, typename... Ts>
requires(detail::tuple_type_count_v<T, Ts...> == 1u)
constexpr decltype(auto) get(const tuple<Ts...> &value) noexcept {
    return get<detail::tuple_type_index<T, Ts...>::value>(value);
}

template<typename T, typename... Ts>
requires(detail::tuple_type_count_v<T, Ts...> == 1u)
constexpr decltype(auto) get(tuple<Ts...> &&value) noexcept {
    return get<detail::tuple_type_index<T, Ts...>::value>(std::move(value));
}

template<typename T, typename... Ts>
requires(detail::tuple_type_count_v<T, Ts...> == 1u)
constexpr decltype(auto) get(const tuple<Ts...> &&value) noexcept {
    return get<detail::tuple_type_index<T, Ts...>::value>(std::move(value));
}

template<size_t I, typename Tuple>
constexpr decltype(auto) tuple_get(Tuple &&value) noexcept {
    return get<I>(std::forward<Tuple>(value));
}

template<typename... Ts>
constexpr auto make_tuple(Ts &&...values) {
    return tuple<std::unwrap_ref_decay_t<Ts>...>{std::forward<Ts>(values)...};
}

template<typename... Ts>
constexpr auto tie(Ts &...values) noexcept {
    return tuple<Ts &...>{values...};
}

template<typename... Ts>
constexpr auto forward_as_tuple(Ts &&...values) noexcept {
    return tuple<Ts &&...>{std::forward<Ts>(values)...};
}

template<typename Function, typename Tuple>
constexpr decltype(auto) apply(Function &&function, Tuple &&value) {
    return detail::apply_impl(std::forward<Function>(function), std::forward<Tuple>(value),
                              std::make_index_sequence<tuple_size_v<Tuple>>{});
}

constexpr tuple<> tuple_cat() noexcept { return {}; }

template<typename Tuple>
constexpr auto tuple_cat(Tuple &&value) {
    return detail::tuple_copy_impl(std::forward<Tuple>(value),
                                   std::make_index_sequence<tuple_size_v<Tuple>>{});
}

template<typename Left, typename Right>
constexpr auto tuple_cat(Left &&left, Right &&right) {
    return detail::tuple_cat_two(std::forward<Left>(left), std::forward<Right>(right));
}

template<typename Left, typename Right, typename... Rest>
constexpr auto tuple_cat(Left &&left, Right &&right, Rest &&...rest) {
    return tuple_cat(detail::tuple_cat_two(std::forward<Left>(left), std::forward<Right>(right)),
                     std::forward<Rest>(rest)...);
}

template<typename... Ts>
constexpr void swap(tuple<Ts...> &left, tuple<Ts...> &right) {
    detail::swap_impl(left, right, std::make_index_sequence<sizeof...(Ts)>{});
}

